import {SITES,MARKETS,getMarket,ROLES,PLATFORMS,PHASES,ELEMENTS,TRAINING_ELEMENTS,uuid,isoToday,daysUntil,datePlus,dateLabel,getPlatform,getPhase,statusOf,createStages} from './data.js';
import {loadLocal,saveLocal,putFile,getFile,removeFile,wipeLocal,exportJson} from './storage.js';
import {cloudEnabled,cloudUser,signIn,signOut,verifyAccess,fetchCloud,insertCloud,updateCloud,removeCloud,uploadCloud,readCloudFile,deleteCloudFile} from './cloud.js';
import {enhanceSelects,refreshSelect,dismissSelectMenus} from './selects.js';
import {sitePlatforms} from './site-presets.js';

const el=document.getElementById('app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=v=>esc(v);
const icons={home:'▦',team:'♧',competencies:'▤',documents:'▱',reminders:'◷',settings:'⚙',chevron:'›',plus:'+',search:'⌕',check:'✓',file:'▤',shield:'✦',clock:'◷',arrow:'↗',download:'↓',upload:'↑'};
let db=cloudEnabled?null:loadLocal();
let ui={page:'overview',search:'',market:'All markets',site:'All sites',status:'All statuses',staff:null,assessment:null,dialog:null,templateTarget:null,menu:false,role:null,loading:false};
const icon=(key)=>`<span class="nav-ico" aria-hidden="true">${icons[key]||'•'}</span>`;
const phrase=(s)=>esc(s);
const on=(selector,evt,fn)=>{document.querySelectorAll(selector).forEach(e=>e.addEventListener(evt,fn));};
const people=()=>db?.employees||[];
const activePeople=()=>people().filter(p=>p.status==='active');
const getEmp=id=>people().find(p=>p.id===id);
const getEnroll=id=>db.enrollments.find(x=>x.id===id);
const getAss=id=>db.assessments.find(x=>x.id===id);
const linked=(en)=>db.assessments.filter(a=>a.enrollment_id===en.id);
const associated=(a)=>getEmp(getEnroll(a.enrollment_id)?.employee_id);
const isManager=()=>!cloudEnabled||['admin','manager'].includes(ui.role?.role);
const isAdmin=()=>!cloudEnabled||ui.role?.role==='admin';
const scopedSites=()=>cloudEnabled?(ui.role?.role!=='admin'?ui.role?.allowed_sites||[]:SITES):[...SITES,...new Set(people().map(p=>p.site).filter(site=>site&&!SITES.includes(site)))];
const visiblePeople=()=>people().filter(p=>scopedSites().includes(p.site));
const visibleEn=()=>db.enrollments.filter(e=>visiblePeople().some(p=>p.id===e.employee_id));
const visibleAss=()=>db.assessments.filter(a=>visibleEn().some(e=>e.id===a.enrollment_id));
const openAss=()=>{return visibleAss().filter(a=>getEmp(getEnroll(a.enrollment_id)?.employee_id)?.status==='active'&&!a.completed_at)};
function notice(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>t.classList.remove('show'),4200)}
const badge=(text,type='neutral')=>`<span class="badge ${type}">${esc(text)}</span>`;
const phaseName=a=>getPhase(a.phase).label+(a.phase==='annual'?` · ${new Date(a.due_date).getFullYear()}`:'');
const statusBadge=(a,p)=>{let s=statusOf(a,p,db.settings?.threshold||30);return badge(({complete:'Complete',overdue:'Overdue',due:'Due soon',archived:'Archived',progress:'In progress',upcoming:'Scheduled'})[s],s);};
const pct=(n,d)=>d?Math.round(100*n/d):0;
function filterSite(p){return (ui.market==='All markets'||getMarket(p.site)?.id===ui.market) && (ui.site==='All sites'||p.site===ui.site);}
function metrics(){const aa=openAss().filter(a=>filterSite(associated(a)||{}));const due=aa.filter(a=>daysUntil(a.due_date)>=0&&daysUntil(a.due_date)<=(db.settings?.threshold||30));const late=aa.filter(a=>daysUntil(a.due_date)<0);const completed=visibleAss().filter(a=>a.completed_at&&filterSite(associated(a)||{}));const team=activePeople().filter(filterSite).filter(p=>scopedSites().includes(p.site));return {aa,due,late,completed,team};}
function navItem(id,title){return `<button class="nav-link ${ui.page===id?'selected':''}" data-nav="${id}">${icon(id)}<span>${title}</span>${id==='reminders'&&metrics().late.length?`<span class="nav-number">${metrics().late.length}</span>`:''}</button>`;}
function sidebar(){return `<aside class="sidebar ${ui.menu?'mobile-open':''}"><div class="brand"><span class="brand-mark"><span class="brand-plus">+</span></span><div><strong>sol<span>lis</span> <i>lab</i></strong><small>COMPETENCY HUB</small></div></div><div class="nav-label">WORKSPACE</div><nav>${navItem('overview','Overview')}${navItem('team','Team directory')}${navItem('competencies','Competencies')}${navItem('documents','Documents')}${navItem('reminders','Reminders')}</nav><div class="nav-label nav-label-last">MANAGEMENT</div><nav>${navItem('settings','Settings')}</nav><div class="sidebar-bottom"><div class="sidebar-info"><span class="sidebar-dot"></span><div><strong>${cloudEnabled?'Cloud workspace':'Local demo'}</strong><small>${cloudEnabled?'Authenticated & private':'Data stays in this browser'}</small></div></div><button class="sidebar-help" data-nav="settings">${icon('shield')} Data & access <span>↗</span></button></div></aside>`;}
function topbar(){return `<header class="topbar"><button class="mobile-menu" id="menu-toggle" aria-label="Open navigation">☰</button><div class="breadcrumb">Workspace <span>/</span> <strong>${({overview:'Overview',team:'Team directory',competencies:'Competencies',documents:'Document library',reminders:'Reminders',settings:'Settings'})[ui.page]}</strong></div><div class="top-right"><span class="date-chip">${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</span>${badge(cloudEnabled?'Connected workspace':'Demo workspace',cloudEnabled?'connected':'demo')}<span class="avatar">${cloudEnabled?'LC':'SH'}</span></div></header>`;}
function shell(content){el.innerHTML=`<div class="layout">${sidebar()}<div class="main"><div>${topbar()}</div><main class="content">${content}</main></div></div><div id="modal-root"></div>`;bindGlobal();enhanceSelects(el);}
function allowedMarkets(){return MARKETS.filter(m=>m.sites.some(site=>scopedSites().includes(site)));}
function marketSelect(id='market-filter',all=true){return `<select class="select" id="${id}" aria-label="Filter by market">${all?'<option value="All markets">All markets</option>':''}${allowedMarkets().map(m=>`<option value="${attr(m.id)}" ${ui.market===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`;}
function siteOptions(sites,selected='',all=false){const legacy=sites.filter(site=>!SITES.includes(site));return `${all?'<option value="All sites">All sites</option>':''}${MARKETS.map(m=>{const available=m.sites.filter(site=>sites.includes(site));return available.length?`<optgroup label="${attr(m.name)}">${available.map(site=>`<option value="${attr(site)}" ${site===selected?'selected':''}>${esc(site)}</option>`).join('')}</optgroup>`:'';}).join('')}${legacy.length?`<optgroup label="Legacy locations — review assignment">${legacy.map(site=>`<option value="${attr(site)}" ${site===selected?'selected':''}>${esc(site)}</option>`).join('')}</optgroup>`:''}`;}
function siteSelect(id='site-filter',all=true){const allowed=scopedSites().filter(site=>ui.market==='All markets'||getMarket(site)?.id===ui.market);return `<select class="select" id="${id}" aria-label="Filter by site">${siteOptions(allowed,ui.site,all)}</select>`;}
function pageHead(kicker,title,description,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function emptyState(title,sub){return `<div class="empty"><div class="empty-symbol">⌕</div><strong>${esc(title)}</strong><p>${esc(sub)}</p></div>`;}
function rowAss(a){const en=getEnroll(a.enrollment_id),em=getEmp(en?.employee_id);if(!em||!en)return '';const d=daysUntil(a.due_date);return `<tr><td><div class="row-person"><span class="initial-avatar ${em.status!=='active'?'dim':''}">${initials(em.name)}</span><div><b>${esc(em.name)}</b><small>${esc(em.role)}</small></div></div></td><td>${esc(getPlatform(en.platform_id).name)}<small class="subcell">${esc(getMarket(em.site)?.name||'Legacy location')} · ${esc(em.site)}</small></td><td>${esc(phaseName(a))}</td><td>${dateLabel(a.due_date)}<small class="subcell ${d<0&&!a.completed_at?'danger-text':''}">${a.completed_at?'Completed '+dateLabel(a.completed_at):d<0?`${Math.abs(d)} days overdue`:d===0?'Due today':`In ${d} days`}</small></td><td>${statusBadge(a,em)}</td><td><button class="icon-button" data-ass="${a.id}" aria-label="Open assessment">↗</button></td></tr>`;}
function initials(s){return (s||'?').split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase();}
function overview(){const m=metrics();const upcoming=[...m.aa].sort((a,b)=>a.due_date.localeCompare(b.due_date)).slice(0,9);const perSite=scopedSites().map(site=>({site,active:m.team.filter(p=>p.site===site).length,due:m.aa.filter(a=>associated(a)?.site===site&&daysUntil(a.due_date)<=30).length})).filter(v=>v.active||v.due);const started=m.completed.filter(a=>daysUntil(a.completed_at)>-365);return `${pageHead('LAB OPERATIONS','Competency overview','One place to track training, assessments, evidence and renewals.',`<button class="button primary" data-action="add-employee">+ Add employee</button>`)}${!cloudEnabled?`<div class="demo-banner"><span>ⓘ</span><div><strong>Demo workspace</strong> The sample employees are fictional. Files are stored in this browser only. Set up a private cloud workspace before entering real employee records.</div><button data-nav="settings">Set up ↗</button></div>`:''}
  <div class="metrics">
   <div class="metric"><div class="metric-top">Active team <span class="metric-icon purple">♙</span></div><strong>${m.team.length}</strong><div class="metric-foot"><span class="teal-text">${m.team.length}</span> assigned across ${perSite.length} sites</div></div>
   <div class="metric"><div class="metric-top">Due within ${db.settings?.threshold||30} days <span class="metric-icon amber">◷</span></div><strong>${m.due.length}</strong><div class="metric-foot">Requires follow-up soon</div></div>
   <div class="metric"><div class="metric-top">Overdue assessments <span class="metric-icon red">!</span></div><strong>${m.late.length}</strong><div class="metric-foot"><span class="danger-text">${m.late.length?'Action needed':'All clear'}</span></div></div>
   <div class="metric"><div class="metric-top">Completed this year <span class="metric-icon green">✓</span></div><strong>${started.length}</strong><div class="metric-foot">Documented competency events</div></div>
  </div>
  <div class="overview-grid"><section class="panel"><div class="section-head"><div><h2>Next up</h2><p>Upcoming and overdue actions across your team</p></div><button class="text-button" data-nav="competencies">View all →</button></div>${upcoming.length?`<div class="table-scroll"><table><thead><tr><th>EMPLOYEE</th><th>TEST SYSTEM</th><th>ASSESSMENT</th><th>DUE DATE</th><th>STATUS</th><th></th></tr></thead><tbody>${upcoming.map(rowAss).join('')}</tbody></table></div>`:emptyState('All caught up','No pending assessments for this site.')}</section><section class="panel site-panel"><div class="section-head"><div><h2>Sites at a glance</h2><p>Open items by location</p></div></div>${perSite.length?MARKETS.map(m=>{const items=perSite.filter(v=>getMarket(v.site)?.id===m.id);return items.length?`<div class="site-market-label">${esc(m.name)}</div>${items.map(v=>`<div class="site-stat"><div class="site-stat-line"><strong>${esc(v.site)}</strong><span>${v.active} staff · ${v.due} open</span></div><div class="track"><span style="width:${Math.min(100,pct(v.due,Math.max(v.active,1)*4))}%"></span></div></div>`).join('')}`:'';}).join('')+((legacy=>legacy.length?`<div class="site-market-label">Legacy locations (review assignments)</div>${legacy.map(v=>`<div class="site-stat"><div class="site-stat-line"><strong>${esc(v.site)}</strong><span>${v.active} staff · ${v.due} open</span></div></div>`).join('')}`:'')(perSite.filter(v=>!getMarket(v.site)))):emptyState('No sites','Add staff to get started.')}<div class="helper-note"><b>Compliance detail</b><p>Each nonwaived competency records all six assessment methods. Assessors, dates, and evidence are preserved separately from training.</p></div></section></div>
  <section class="panel"><div class="section-head"><div><h2>Workflow</h2><p>A consistent progression for every assigned instrument or test system</p></div></div><div class="workflow"><div><span class="stage-count">01</span><b>Initial training</b><small>SOP, operation, QC and trainer sign-off</small></div><span class="workflow-arrow">→</span><div><span class="stage-count">02</span><b>Initial assessment</b><small>Competence before independent testing</small></div><span class="workflow-arrow">→</span><div><span class="stage-count">03</span><b>6-month review</b><small>First-year competency assessment</small></div><span class="workflow-arrow">→</span><div><span class="stage-count">04</span><b>Annual renewal</b><small>Recurring yearly documentation</small></div></div></section>`;}
function team(){let filtered=visiblePeople().filter(p=>filterSite(p)).filter(p=>`${p.name} ${p.site} ${p.role}`.toLowerCase().includes(ui.search.toLowerCase())).filter(p=>ui.status==='All statuses'||(ui.status==='Active'&&p.status==='active')||(ui.status==='Offboarded'&&p.status==='offboarded'));const rows=filtered.sort((a,b)=>Number(a.status!=='active')-Number(b.status!=='active')||a.name.localeCompare(b.name));return `${pageHead('TEAM MANAGEMENT','Team directory','Manage access to instruments, competency timelines and offboarding.',isManager()?`<button class="button primary" data-action="add-employee">+ Add employee</button>`:'')}
<div class="filter-bar"><div class="search-box">⌕ <input id="search" placeholder="Search employees, role or location..." value="${attr(ui.search)}" /></div>${marketSelect()}${siteSelect()}<select class="select" id="status-filter">${['All statuses','Active','Offboarded'].map(s=>`<option ${ui.status===s?'selected':''}>${s}</option>`).join('')}</select></div>
<section class="panel table-panel">${rows.length?`<div class="table-scroll"><table><thead><tr><th>EMPLOYEE</th><th>LOCATION</th><th>ONBOARDING</th><th>ASSIGNED SYSTEMS</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(p=>{const ens=db.enrollments.filter(e=>e.employee_id===p.id);const tasks=ens.flatMap(linked).filter(a=>!a.completed_at&&daysUntil(a.due_date)<0);return `<tr><td><div class="row-person"><span class="initial-avatar">${initials(p.name)}</span><div><b>${esc(p.name)}</b><small>${esc(p.role)}</small></div></div></td><td>${esc(p.site)}<small class="subcell">${esc(getMarket(p.site)?.name||'Legacy location')}</small></td><td>${dateLabel(p.hire_date)}</td><td>${ens.length} systems ${tasks.length?badge(`${tasks.length} overdue`,'overdue'):''}</td><td>${p.status==='active'?badge('Active','connected'):badge((p.offboard_reason||'Offboarded'),'archived')}</td><td><button class="icon-button" data-staff="${p.id}" aria-label="Open employee">↗</button></td></tr>`}).join('')}</tbody></table></div>`:emptyState('No employees found','Try changing the search or status filters.')}</section>`;}
function competencies(){let rows=visibleAss().filter(a=>filterSite(associated(a)||{}));rows=rows.filter(a=>{const en=getEnroll(a.enrollment_id),em=getEmp(en?.employee_id);return `${em?.name||''} ${getPlatform(en?.platform_id).name} ${a.phase}`.toLowerCase().includes(ui.search.toLowerCase())});if(ui.status!=='All statuses')rows=rows.filter(a=>{const em=associated(a),s=statusOf(a,em,db.settings.threshold);return s===({Overdue:'overdue','Due soon':'due',Completed:'complete',Scheduled:'upcoming',Archived:'archived'}[ui.status]||'notfound')});rows.sort((a,b)=>(a.completed_at?1:0)-(b.completed_at?1:0)||a.due_date.localeCompare(b.due_date));return `${pageHead('ASSESSMENT TRACKER','Competencies','Track every test system independently, with evidence for each evaluation.',`<button class="button secondary" data-nav="reminders">◷ View due items</button>`)}<div class="filter-bar"><div class="search-box">⌕ <input id="search" placeholder="Search employee or test system..." value="${attr(ui.search)}"/></div>${marketSelect()}${siteSelect()}<select class="select" id="status-filter">${['All statuses','Overdue','Due soon','Completed','Scheduled','Archived'].map(s=>`<option ${ui.status===s?'selected':''}>${s}</option>`).join('')}</select></div><section class="panel table-panel"><div class="section-head table-heading"><div><h2>Assessment records <span class="count">${rows.length}</span></h2><p>Training, initial assessment, six-month check and annual renewals</p></div></div><div class="table-scroll"><table><thead><tr><th>EMPLOYEE</th><th>TEST SYSTEM</th><th>STAGE</th><th>DUE / COMPLETED</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.slice(0,300).map(rowAss).join('')}</tbody></table></div>${rows.length>300?'<div class="small-warning">Showing first 300 records. Refine filters to see more.</div>':''}${!rows.length?emptyState('No competency records','Assign a test system to an employee to populate the tracker.'):''}</section>`;}
function docs(){const docs=db.documents.filter(d=>!d.employee_id||visiblePeople().some(p=>p.id===d.employee_id)).filter(d=>!d.employee_id||filterSite(getEmp(d.employee_id)||{}));const catalog=PLATFORMS.filter(p=>p.source);return `${pageHead('EVIDENCE & RECORDS','Document library','Keep competency evidence linked to the correct employee and assessment.',isManager()?`<button class="button primary" data-action="upload-template">↑ Add reference template</button>`:'')}
<div class="document-banner"><div><span class="banner-emblem">▣</span></div><div><strong>Recommended file organization</strong><p>Employee → test system → assessment year. Upload signed checklists, QC printouts, competency worksheets and remediation evidence. Shared reference checklists remain separate from employee records.</p></div></div>
<div class="docs-layout"><section class="panel"><div class="section-head"><div><h2>Employee documents <span class="count">${docs.filter(d=>d.employee_id).length}</span></h2><p>Only assigned users should have access to sensitive files.</p></div></div>${docs.filter(d=>d.employee_id).length?`<div class="table-scroll"><table><thead><tr><th>DOCUMENT</th><th>EMPLOYEE</th><th>UPLOADED</th><th></th></tr></thead><tbody>${docs.filter(d=>d.employee_id).slice().reverse().map(d=>`<tr><td><div class="doc-name"><span class="file-icon">▤</span><div><b>${esc(d.file_name)}</b><small>${esc(d.mime_type||'Linked document')}</small></div></div></td><td>${esc(getEmp(d.employee_id)?.name||'Unknown')}</td><td>${dateLabel((d.created_at||'').slice(0,10))}</td><td><button class="icon-button" data-file="${d.id}" aria-label="Open document">↗</button></td></tr>`).join('')}</tbody></table></div>`:emptyState('No employee evidence yet','Open an assessment and upload a signed training checklist, competency record or QC documentation.')}</section><section class="panel"><div class="section-head"><div><h2>Reference templates</h2><p>${catalog.length} provided checklists + new templates</p></div></div><div class="template-list">${catalog.map(p=>{const attached=docs.find(d=>d.platform_id===p.id&&!d.employee_id);return `<div class="template-row"><div class="template-file">▤</div><div><b>${esc(p.name)}</b><small>${attached?esc(attached.file_name):esc(p.source)}</small></div>${attached?`<button class="mini-button" data-file="${attached.id}">Open ↗</button>`:isManager()?`<button class="mini-button" data-template="${p.id}">Upload</button>`:''}</div>`}).join('')}${docs.filter(d=>!d.employee_id&&!catalog.some(p=>p.id===d.platform_id)).map(d=>`<div class="template-row"><div class="template-file">▤</div><div><b>${esc(d.file_name)}</b><small>Shared reference</small></div><button class="mini-button" data-file="${d.id}">Open ↗</button></div>`).join('')}</div><div class="template-tip">The original templates are bundled in <code>private_templates/</code>. Upload them to private cloud storage before use. They are not published on the website.</div></section></div>`;}
function reminders(){const open=openAss().filter(a=>filterSite(associated(a)||{}));const groups=[{title:'Overdue',cls:'overdue',items:open.filter(a=>daysUntil(a.due_date)<0)},{title:'Due in 7 days',cls:'due',items:open.filter(a=>daysUntil(a.due_date)>=0&&daysUntil(a.due_date)<=7)},{title:'Due in 8–30 days',cls:'upcoming',items:open.filter(a=>daysUntil(a.due_date)>=8&&daysUntil(a.due_date)<=30)},{title:'Due in 31–60 days',cls:'upcoming',items:open.filter(a=>daysUntil(a.due_date)>=31&&daysUntil(a.due_date)<=60)}];return `${pageHead('SCHEDULED FOLLOW-UPS','Reminders','See deadlines now. In cloud mode, enable a scheduled email digest using the included function.',`<button class="button secondary" data-nav="settings">⚙ Configure reminders</button>`)}<div class="reminder-summary"><span>◷</span><div><strong>Reminder schedule</strong><p>Suggested notices at 30, 14, 7 and 0 days before due date, then weekly while overdue. Offboarded employees are excluded automatically.</p></div><span class="reminder-mode">${cloudEnabled?'Email scheduler setup required':'On-screen only in demo'}</span></div><div class="reminder-columns">${groups.map(g=>`<section class="panel reminder-list"><div class="reminder-title"><h2>${g.title}</h2>${badge(g.items.length,g.cls)}</div>${g.items.length?g.items.sort((a,b)=>a.due_date.localeCompare(b.due_date)).slice(0,16).map(a=>{const en=getEnroll(a.enrollment_id),em=getEmp(en.employee_id);return `<button class="remind-item" data-ass="${a.id}"><div><b>${esc(em?.name)}</b><small>${esc(getPlatform(en.platform_id).name)} · ${esc(getPhase(a.phase).short)}</small></div><div><strong>${dateLabel(a.due_date)}</strong><small>${daysUntil(a.due_date)<0?`${Math.abs(daysUntil(a.due_date))}d late`:`${daysUntil(a.due_date)}d left`}</small></div></button>`;}).join(''):emptyState('Nothing pending','No items in this window.')}</section>`).join('')}</div>`;}
function settings(){return `${pageHead('WORKSPACE','Settings','Manage document storage, alert thresholds and your workspace data.')}
 <div class="settings-grid"><section class="panel pad-panel"><h2>Storage & privacy</h2><p class="muted">Your current workspace mode and how files are stored.</p><div class="setting-row"><span>Workspace mode</span>${badge(cloudEnabled?'Private cloud':'Local demo',cloudEnabled?'connected':'demo')}</div><div class="setting-row"><span>Document storage</span><b>${cloudEnabled?'Supabase private bucket':'This browser (IndexedDB)'}</b></div><div class="setting-row"><span>Access control</span><b>${cloudEnabled?'Login + row-level security':'None (local only)'}</b></div><div class="setting-row"><span>Backup coverage</span><b>${cloudEnabled?'Managed cloud, configure backups':'Manual metadata export'}</b></div><div class="info-block"><strong>Recommended for your team</strong><p>If Sollis already uses Microsoft 365, a restricted SharePoint document library is the easiest place to store signed PDFs. Paste a secure SharePoint document link into an assessment. For upload directly from this website, connect Supabase with the included private bucket and RLS rules.</p></div>${cloudEnabled?`<button class="button secondary" id="signout">Sign out</button>`:`<button class="button secondary" id="export">↓ Export metadata</button><p class="warning-text">A local export contains records and links, not the uploaded file contents. Do not use demo mode as the official record system.</p>`}</section>
 <section class="panel pad-panel"><h2>Competency & reminders</h2><p class="muted">Due dates are calculated from each test system's first-testing date, not necessarily hire date.</p><label class="field"><span>Due-soon window</span><select id="threshold" class="select">${[7,14,30,45,60].map(n=>`<option value="${n}" ${db.settings?.threshold===n?'selected':''}>${n} days</option>`).join('')}</select></label><div class="setting-row"><span>Initial training and assessment</span><b>Before independent testing</b></div><div class="setting-row"><span>First-year follow-up</span><b>6 months</b></div><div class="setting-row"><span>Annual recurring</span><b>Every 12 months</b></div><p class="warning-text">Your laboratory director and accreditation requirements control the actual due dates. Review system complexity and local policy before using these schedules for compliance.</p></section>
 <section class="panel pad-panel"><h2>Included assets</h2><p class="muted">Your uploaded training checklist archive has been included privately in the project download.</p><div class="setting-row"><span>Source checklists</span><b>${PLATFORMS.filter(p=>p.source).length} matched platforms</b></div><div class="setting-row"><span>Additional platforms</span><b>PATHFAST, Triage, FebriDx</b></div><div class="setting-row"><span>External document links</span><b>Supported</b></div><button class="button secondary" data-nav="documents">See template library →</button></section>
 <section class="panel pad-panel"><h2>Launch checklist</h2><div class="launch-row"><span>1</span> Create a Supabase project and run <code>supabase/schema.sql</code></div><div class="launch-row"><span>2</span> Create authorized accounts and apply site access controls</div><div class="launch-row"><span>3</span> Set project URL and publishable key in <code>config.js</code></div><div class="launch-row"><span>4</span> Deploy to a private company-approved host</div><div class="launch-row"><span>5</span> Set up the email scheduler and test with fictional data</div><p class="muted">The README includes the full configuration steps, including the automated reminder function.</p></section></div>`;}
function render(){dismissSelectMenus();if(cloudEnabled&&!cloudUser()){loginPage();return;}if(cloudEnabled&&!db){el.innerHTML='<div class="loading">Loading secure workspace…</div>';return;}const p=({overview,team,competencies,documents:docs,reminders,settings})[ui.page]||overview;shell(p());if(ui.staff)showEmployee(ui.staff);if(ui.assessment)showAssessment(ui.assessment);if(ui.dialog)showDialog(ui.dialog);}
function loginPage(){el.innerHTML=`<div class="login-page"><div class="login-card"><div class="brand login-brand"><span class="brand-mark"><span class="brand-plus">+</span></span><div><strong>sol<span>lis</span> <i>lab</i></strong><small>COMPETENCY HUB</small></div></div><h1>Welcome back</h1><p>Sign in to the private competency workspace.</p><form id="login-form"><label class="field"><span>Email address</span><input required type="email" name="email" autocomplete="username" placeholder="you@company.com"/></label><label class="field"><span>Password</span><input required type="password" name="password" autocomplete="current-password" placeholder="Your password"/></label><button type="submit" class="button primary full">Sign in securely →</button></form><div class="login-privacy">✦ Access is limited to approved staff. Your administrator controls site permissions.</div></div></div>`;document.getElementById('login-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;button.textContent='Signing in…';try{await signIn(form.email.value.trim(),form.password.value);ui.role=await verifyAccess();db=await fetchCloud();render()}catch(err){signOut();notice(err.message);button.disabled=false;button.textContent='Sign in securely →';}});}
function bindGlobal(){on('[data-nav]','click',e=>{ui.page=e.currentTarget.dataset.nav;ui.search='';ui.status='All statuses';ui.staff=null;ui.assessment=null;ui.dialog=null;ui.menu=false;render();});on('[data-staff]','click',e=>{ui.staff=e.currentTarget.dataset.staff;render()});on('[data-ass]','click',e=>{ui.assessment=e.currentTarget.dataset.ass;render()});on('[data-action]','click',e=>{ui.dialog=e.currentTarget.dataset.action;render()});on('[data-file]','click',e=>downloadDoc(e.currentTarget.dataset.file));on('[data-template]','click',e=>{ui.templateTarget=e.currentTarget.dataset.template;ui.dialog='upload-template';render()});const search=document.getElementById('search');if(search)search.addEventListener('input',e=>{const pos=e.target.selectionStart;ui.search=e.target.value;render();const next=document.getElementById('search');if(next){next.focus();next.setSelectionRange(pos,pos)}});const marketFilter=document.getElementById('market-filter');if(marketFilter)marketFilter.addEventListener('change',e=>{ui.market=e.target.value;ui.site='All sites';render()});const f=document.getElementById('site-filter');if(f)f.addEventListener('change',e=>{ui.site=e.target.value;render()});const s=document.getElementById('status-filter');if(s)s.addEventListener('change',e=>{ui.status=e.target.value;render()});const menu=document.getElementById('menu-toggle');if(menu)menu.addEventListener('click',()=>{ui.menu=!ui.menu;render()});const threshold=document.getElementById('threshold');if(threshold)threshold.addEventListener('change',e=>{db.settings.threshold=Number(e.target.value);if(!cloudEnabled)saveLocal(db);render();notice('Due-soon window updated for this browser.')});const exp=document.getElementById('export');if(exp)exp.addEventListener('click',()=>exportJson(db));const so=document.getElementById('signout');if(so)so.addEventListener('click',()=>{signOut();db=null;ui.role=null;render()});}
function modal(content,cls=''){dismissSelectMenus();const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-overlay" id="overlay"><div class="modal ${cls}" role="dialog" aria-modal="true">${content}</div></div>`;root.querySelector('#overlay').addEventListener('mousedown',e=>{if(e.target===e.currentTarget)closeOverlays()});on('.modal-close','click',closeOverlays);enhanceSelects(root);document.onkeydown=e=>{if(e.key==='Escape')closeOverlays()};}
function closeOverlays(){dismissSelectMenus();ui.staff=null;ui.assessment=null;ui.dialog=null;ui.templateTarget=null;const root=document.getElementById('modal-root');if(root)root.innerHTML='';}
function modalHead(eyebrow,title,sub=''){return `<div class="modal-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div><button class="modal-close" aria-label="Close">×</button></div>`;}
async function addRecords(table,records){if(cloudEnabled){const saved=await insertCloud(table,records);db[table].push(...saved);}else{db[table].push(...records);saveLocal(db);}}
async function patch(table,id,obj){if(cloudEnabled){await updateCloud(table,id,obj);}const target=db[table].find(x=>x.id===id);if(target)Object.assign(target,obj);if(!cloudEnabled)saveLocal(db);}
async function removeRecord(table,id){if(cloudEnabled)await removeCloud(table,id);db[table]=db[table].filter(r=>r.id!==id);if(!cloudEnabled)saveLocal(db);}
function showDialog(kind){if(kind==='add-employee')return addEmployeeDialog();if(kind==='assign-platform')return assignPlatformDialog();if(kind==='offboard')return offboardDialog();if(kind==='upload-template')return templateDialog();}
function addEmployeeDialog(){modal(`${modalHead('ONBOARDING','Add new employee','Add the employee first, then assign test systems and assessment start dates.')}
<form id="employee-form" class="form-body"><div class="form-grid"><label class="field"><span>Full name *</span><input name="name" required placeholder="Employee full name"/></label><label class="field"><span>Role *</span><select name="role" required>${ROLES.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field"><span>Market *</span><select name="market" id="employee-market" required>${allowedMarkets().map(m=>`<option value="${attr(m.id)}">${esc(m.name)}</option>`).join('')}</select></label><label class="field"><span>Site *</span><select name="site" id="employee-site" required>${siteOptions(scopedSites().filter(site=>getMarket(site)?.id===allowedMarkets()[0]?.id))}</select></label><label class="field"><span>Hire date *</span><input type="date" name="hire_date" required value="${isoToday()}"/></label></div><label class="field"><span>Work email (optional)</span><input name="email" type="email" placeholder="staff@company.com"/></label><div class="notice-box">Instrument-specific first-testing dates are set when you assign a platform. The hire date does not automatically start every competency clock.</div><div class="form-actions"><button type="button" class="button secondary modal-close">Cancel</button><button type="submit" class="button primary">Add employee →</button></div></form>`);
 const form=document.getElementById('employee-form');const employeeMarket=document.getElementById('employee-market');const employeeSite=document.getElementById('employee-site');employeeMarket?.addEventListener('change',()=>{employeeSite.innerHTML=siteOptions(scopedSites().filter(site=>getMarket(site)?.id===employeeMarket.value));});form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form);const record={id:uuid(),name:String(f.get('name')).trim(),role:f.get('role'),site:f.get('site'),hire_date:f.get('hire_date'),email:f.get('email'),status:'active',offboard_reason:null,offboarded_at:null,created_at:new Date().toISOString()};if(!record.name)return;if(!scopedSites().includes(record.site)||getMarket(record.site)?.id!==f.get('market')){notice('Select a valid site within the selected market.');return;}try{await addRecords('employees',[record]);closeOverlays();ui.staff=record.id;render();notice('Employee added. Assign their first test system.')}catch(err){notice(err.message)}});}
function showEmployee(id){const p=getEmp(id);if(!p){closeOverlays();return;}const ens=db.enrollments.filter(e=>e.employee_id===id);const archived=p.status==='offboarded';modal(`${modalHead('EMPLOYEE PROFILE',p.name,`${p.role} · ${getMarket(p.site)?.name||'Legacy location'} · ${p.site}`)}<div class="employee-header"><span class="profile-avatar">${initials(p.name)}</span><div><div>${archived?badge(p.offboard_reason==='terminated'?'Terminated':'Resigned','archived'):badge('Active employee','connected')}</div><small>Hired ${dateLabel(p.hire_date)}${p.email?' · '+esc(p.email):''}</small></div></div><div class="profile-tools">${isManager()&&!archived?`<button class="button primary small" id="assign">+ Assign test system</button>`:''}${isAdmin()&&!archived?`<button class="button light-danger small" id="offboard">Offboard employee</button>`:''}${archived?`<span class="archived-note">Offboarded ${dateLabel(p.offboarded_at?.slice(0,10))}. Historical records retained.</span>`:''}</div><div class="subheading">Test system assignments <span class="count">${ens.length}</span></div>${ens.length?`<div class="enrollment-list">${ens.map(en=>{const entries=linked(en);const done=entries.filter(a=>a.completed_at).length,late=entries.filter(a=>!a.completed_at&&daysUntil(a.due_date)<0).length;return `<div class="en-card"><div class="en-title"><div><strong>${esc(getPlatform(en.platform_id).name)}</strong><small>First testing ${dateLabel(en.first_testing_date)} · ${getPlatform(en.platform_id).group}</small></div>${badge(`${done}/${entries.length} complete`,'neutral')}</div><div class="en-stages">${entries.filter(a=>a.phase!=='annual'||daysUntil(a.due_date)<370).sort((a,b)=>a.due_date.localeCompare(b.due_date)).map(a=>`<button class="stage-chip" data-ass="${a.id}"><span>${esc(getPhase(a.phase).short)}${a.phase==='annual'?` ${a.cycle}`:''}</span>${statusBadge(a,p)}</button>`).join('')}</div>${late?`<small class="danger-text">${late} overdue assessment${late!==1?'s':''}</small>`:''}</div>`}).join('')}</div>`:emptyState('No assigned systems','Assign an instrument to start tracking training and competency.')}`, 'wide-modal');on('#assign','click',()=>{ui.dialog='assign-platform';ui.assessment=null;render()});on('#offboard','click',()=>{ui.dialog='offboard';render()});on('.stage-chip','click',e=>{ui.staff=null;ui.dialog=null;ui.assessment=e.currentTarget.dataset.ass;render()});}
function assignPlatformDialog(){const staff=ui.staff;const p=getEmp(staff);if(!p)return;const assigned=db.enrollments.filter(e=>e.employee_id===staff).map(e=>e.platform_id);const available=sitePlatforms(p.site).filter(t=>!assigned.includes(t.id));modal(`${modalHead('TEST SYSTEM ENROLLMENT','Assign a test system',`Employee: ${p.name}`)}${available.length?`<form class="form-body" id="assign-form"><label class="field"><span>Test system *</span><select name="platform" id="platform-select" required>${available.map(t=>`<option value="${t.id}">${esc(t.name)} · ${esc(t.group)}</option>`).join('')}</select></label><div class="form-grid"><label class="field"><span>First-testing / assessment start date *</span><input type="date" required name="first_testing_date" value="${isoToday()}"/></label><label class="field"><span>Applicable policy *</span><select name="complexity" id="policy-select"><option value="nonwaived">Nonwaived: six elements</option><option value="waived">Waived: site-specific</option><option value="site-policy">Other: site policy</option></select></label></div><div class="notice-box">This creates four milestones: initial training, initial competency, six-month competency and annual assessments. Choose the actual first-testing date for this platform, not automatically the date of hire. Confirm test complexity with your laboratory director.</div><div class="form-actions"><button type="button" class="button secondary modal-close">Cancel</button><button type="submit" class="button primary">Assign & schedule</button></div></form>`:emptyState('All systems assigned','All systems available at this site are already assigned.')}`,'wide-modal');const select=document.getElementById('platform-select'),policy=document.getElementById('policy-select');if(select){const sync=()=>policy.value=getPlatform(select.value).mode;sync();select.addEventListener('change',sync);}const form=document.getElementById('assign-form');if(form)form.addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(form),en={id:uuid(),employee_id:staff,platform_id:f.get('platform'),first_testing_date:f.get('first_testing_date'),complexity:f.get('complexity'),created_at:new Date().toISOString()};if(!en.first_testing_date)return;try{await addRecords('enrollments',[en]);await addRecords('assessments',createStages(en));ui.dialog=null;ui.staff=staff;render();notice('Test system assigned and milestones scheduled.')}catch(err){notice(err.message);await refreshCloud()}});}
function offboardDialog(){const p=getEmp(ui.staff);if(!p)return;modal(`${modalHead('STAFF OFFBOARDING','Offboard employee',`Employee: ${p.name}`)}<form id="offboard-form" class="form-body"><div class="notice-box caution"><strong>Historical records will be preserved.</strong><p>New reminders stop. Completed assessments, documents and sign-offs remain accessible to authorized administrators. This does not deactivate the employee's login or revoke external SharePoint access.</p></div><label class="field"><span>Reason *</span><select name="reason"><option value="resigned">Resigned / departed voluntarily</option><option value="terminated">Terminated / involuntary separation</option></select></label><label class="field"><span>Offboarding date *</span><input type="date" name="date" value="${isoToday()}" required/></label><label class="field"><span>Type employee name to confirm *</span><input name="confirm" required placeholder="${attr(p.name)}"/></label><div class="form-actions"><button type="button" class="button secondary modal-close">Cancel</button><button type="submit" class="button light-danger">Confirm offboarding</button></div></form>`);document.getElementById('offboard-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('confirm')!==p.name)return notice('Name does not match. Offboarding cancelled.');try{await patch('employees',p.id,{status:'offboarded',offboard_reason:f.get('reason'),offboarded_at:`${f.get('date')}T12:00:00Z`});ui.dialog=null;render();notice('Employee offboarded. Competency records preserved; reminders stopped.')}catch(err){notice(err.message)}});}
function showAssessment(id){const a=getAss(id);if(!a){closeOverlays();return;}const en=getEnroll(a.enrollment_id),p=getEmp(en?.employee_id);if(!en||!p)return;const mode=en.complexity,training=a.phase==='initial_training',items=training?TRAINING_ELEMENTS:ELEMENTS;const locked=p.status!=='active'||!isManager()||Boolean(a.completed_at);const uploaded=db.documents.filter(d=>d.assessment_id===a.id);const checked=new Set(a.elements||[]);modal(`${modalHead('COMPETENCY RECORD',getPlatform(en.platform_id).name,`${esc(p.name)} · ${getPhase(a.phase).label}`)}
<div class="assessment-strip"><div><small>ASSESSMENT DUE</small><strong>${dateLabel(a.due_date)}</strong></div><div><small>FIRST TESTING DATE</small><strong>${dateLabel(en.first_testing_date)}</strong></div><div><small>REQUIREMENT</small><strong>${mode==='nonwaived'?'Six assessment elements':mode==='waived'?'Waived / site policy':'Site policy'}</strong></div>${statusBadge(a,p)}</div>
<form id="assessment-form" class="form-body"><div class="section-head form-section-head"><div><h2>${training?'Initial training checklist':'Assessment methods'}</h2><p>${training?'Verify each required training step with the trainer.':mode==='nonwaived'?'Document all six CLIA assessment procedures as applicable to the test system.':'Document elements required by your site policy. The six-element list is available as a guide.'}</p></div></div>
<div class="element-list">${items.map((t,i)=>`<label class="element-row ${checked.has(i)?'checked':''}"><input type="checkbox" name="element" value="${i}" ${checked.has(i)?'checked':''} ${locked?'disabled':''}/><span class="check-ui">✓</span><span><small>METHOD ${String(i+1).padStart(2,'0')}</small><b>${esc(t)}</b></span></label>`).join('')}</div>
<div class="form-grid"><label class="field"><span>Assessment outcome</span><select name="outcome" ${locked?'disabled':''}><option value="pending">Pending</option><option value="competent" ${a.outcome==='competent'?'selected':''}>Competent</option><option value="remediation" ${a.outcome==='remediation'?'selected':''}>Remediation needed</option></select></label><label class="field"><span>Assessor / trainer</span><input name="assessor" placeholder="Qualified assessor's full name" value="${attr(a.assessor||'')}" ${locked?'disabled':''}/></label></div><label class="field"><span>Notes, evidence reviewed or remediation plan</span><textarea name="notes" rows="3" placeholder="Document observations, QC references, any remediation and follow-up." ${locked?'disabled':''}>${esc(a.notes||'')}</textarea></label><label class="field"><span>Assessment / sign-off date</span><input type="date" name="completed_at" value="${a.completed_at?.slice(0,10)||isoToday()}" ${locked?'disabled':''}/></label>
<div class="section-head form-section-head"><div><h2>Supporting documents <span class="count">${uploaded.length}</span></h2><p>Signed training checklist, instrument QC, PT, competency forms or remediation evidence</p></div></div><div class="file-rows">${uploaded.map(d=>`<button type="button" class="attachment" data-file="${d.id}"><span>▤</span><div><b>${esc(d.file_name)}</b><small>${dateLabel((d.created_at||'').slice(0,10))} · ${esc(d.mime_type||'Link')}</small></div><strong>Open ↗</strong></button>`).join('')}${!uploaded.length?'<p class="muted">No documents attached to this assessment yet.</p>':''}</div>
${!locked?`<div class="attachment-actions"><label class="button secondary file-input-btn">↑ Upload PDF or file <input type="file" id="assessment-upload" accept=".pdf,.doc,.docx,.png,.jpg,.jpeg,.xlsx" hidden/></label><button type="button" class="button secondary" id="add-link">+ Link SharePoint file</button></div>`:''}
${a.completed_at?`<div class="notice-box success"><strong>Recorded complete on ${dateLabel(a.completed_at)}</strong> by ${esc(a.assessor||'assessor not recorded')}. This record is locked to preserve the sign-off history.</div>`:''}
${p.status==='offboarded'?'<div class="notice-box caution">This employee is offboarded. All records are read-only.</div>':''}
${!locked?`<div class="form-actions"><button type="button" class="button secondary" id="save-progress">Save progress</button><button type="submit" class="button primary">Complete assessment ✓</button></div>`:''}</form>`,'assessment-modal');
 on('.element-row input','change',e=>e.currentTarget.closest('.element-row').classList.toggle('checked',e.currentTarget.checked));on('.attachment','click',e=>downloadDoc(e.currentTarget.dataset.file));const u=document.getElementById('assessment-upload');if(u)u.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{await addDocument({employee_id:p.id,assessment_id:a.id,platform_id:en.platform_id},file);ui.assessment=id;render();notice('File attached to competency record.')}catch(err){notice(err.message)}});on('#add-link','click',()=>sharePointLink({employee_id:p.id,assessment_id:a.id,platform_id:en.platform_id}));on('#save-progress','click',()=>saveAssessment(false));const f=document.getElementById('assessment-form');if(f)f.addEventListener('submit',e=>{e.preventDefault();saveAssessment(true)});
 async function saveAssessment(complete){if(locked)return;const f=document.getElementById('assessment-form');const fields=new FormData(f);const elements=[...f.querySelectorAll('[name="element"]:checked')].map(x=>Number(x.value));const assessor=String(fields.get('assessor')||'').trim();const outcome=fields.get('outcome');const date=fields.get('completed_at');if(complete){if(!assessor)return notice('Enter the qualified assessor / trainer.');if(!date)return notice('Enter the assessment date.');if(outcome!=='competent')return notice('Choose Competent to complete. Remediation items remain open.');if((training||mode==='nonwaived')&&elements.length!==items.length)return notice('All required assessment methods / training steps must be checked before completion.');}
 try{await patch('assessments',id,{started_at:a.started_at||new Date().toISOString(),elements,assessor,notes:String(fields.get('notes')||''),outcome,completed_at:complete?`${date}T12:00:00Z`:null});render();notice(complete?'Assessment completed and locked.':'Assessment progress saved.')}catch(err){notice(err.message)}}
}
async function addDocument(ref,file,externalUrl){if(!isManager())throw Error('Insufficient permission to upload');if(!externalUrl&&file.size>25*1024*1024)throw Error('Max 25 MB per file.');if(!externalUrl&&!['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','image/png','image/jpeg'].includes(file.type)&&!(/\.(pdf|doc|docx|xlsx|png|jpe?g)$/i).test(file.name))throw Error('Accepted: PDF, Word, Excel, PNG or JPG.');
 const id=uuid(),filename=externalUrl?file.name:file.name.replace(/[^\p{L}\p{N}._ -]/gu,'_').slice(0,110);const path=externalUrl?null:(ref.employee_id?`${ref.employee_id}/${ref.assessment_id||'general'}/${id}-${filename}`:`templates/${ref.platform_id||'general'}/${id}-${filename}`);
 if(!externalUrl){if(cloudEnabled)await uploadCloud(path,file);else await putFile(path,file);}const record={id,employee_id:ref.employee_id||null,assessment_id:ref.assessment_id||null,platform_id:ref.platform_id||null,file_name:filename,mime_type:externalUrl?'external/link':(file.type||'application/octet-stream'),storage_path:path,external_url:externalUrl||null,created_at:new Date().toISOString()};try{await addRecords('documents',[record])}catch(err){if(!cloudEnabled&&path)await removeFile(path);throw err}}
async function downloadDoc(id){const d=db.documents.find(x=>x.id===id);if(!d)return;if(d.external_url){try{const url=new URL(d.external_url);if(url.protocol!=='https:'||!/(^|\.)sharepoint\.com$|(^|\.)onedrive\.com$/.test(url.hostname))throw Error('Link is not an approved SharePoint / OneDrive URL');window.open(url.href,'_blank','noopener,noreferrer');}catch(err){notice(err.message)}return;}try{const file=cloudEnabled?await readCloudFile(d.storage_path):await getFile(d.storage_path);if(!file){notice('File not found in this browser. It may have been saved in another browser.');return;}const blobUrl=URL.createObjectURL(file);const link=document.createElement('a');link.href=blobUrl;link.download=d.file_name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(blobUrl),30000)}catch(err){notice(err.message)}}
function sharePointLink(ref){modal(`${modalHead('LINK EXTERNAL DOCUMENT','Link SharePoint file','Use a private document link with company access permissions.')}
<form class="form-body" id="link-form"><label class="field"><span>Document title *</span><input name="title" required placeholder="Signed annual competency.pdf"/></label><label class="field"><span>Secure document URL *</span><input name="url" type="url" required placeholder="https://yourcompany.sharepoint.com/..." /></label><div class="notice-box">Never use an “Anyone with the link” sharing setting for employee competency records. Access is controlled by the linked file's owner, not this website.</div><div class="form-actions"><button type="button" class="button secondary modal-close">Cancel</button><button type="submit" class="button primary">Save link</button></div></form>`);document.getElementById('link-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),url=f.get('url');try{const parsed=new URL(url);if(parsed.protocol!=='https:')throw Error('HTTPS links only.');if(!/(^|\.)sharepoint\.com$|(^|\.)onedrive\.com$/.test(parsed.hostname))throw Error('Use a SharePoint or OneDrive URL for employee files.');await addDocument(ref,{name:f.get('title')},url);ui.assessment=ref.assessment_id;render();notice('Secure document link saved.')}catch(err){notice(err.message)}});}
function templateDialog(){const target=ui.templateTarget||PLATFORMS[0].id;modal(`${modalHead('REFERENCE LIBRARY','Upload a training template','Upload the source checklist to the private template library.')}
<form class="form-body" id="template-form"><label class="field"><span>Test system</span><select name="platform">${PLATFORMS.map(t=>`<option value="${t.id}" ${target===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label class="field"><span>Reference file</span><input type="file" required name="file" accept=".pdf,.doc,.docx,.xlsx,.png,.jpg,.jpeg"/></label><div class="notice-box">Your original 16 documents are included in the <code>private_templates</code> directory of the download. Upload here after configuring the secure workspace.</div><div class="form-actions"><button type="button" class="button secondary modal-close">Cancel</button><button type="submit" class="button primary">Upload template</button></div></form>`);document.getElementById('template-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),file=f.get('file');if(!file?.name)return;try{await addDocument({employee_id:null,assessment_id:null,platform_id:f.get('platform')},file);ui.dialog=null;ui.templateTarget=null;render();notice('Reference template saved.')}catch(err){notice(err.message)}});}
async function refreshCloud(){if(cloudEnabled){try{db=await fetchCloud()}catch(e){notice(e.message)}render()}}
async function bootstrap(){if(!cloudEnabled){render();return;}if(cloudUser()){try{ui.role=await verifyAccess();db=await fetchCloud()}catch(e){signOut();db=null;notice(e.message)}}render();}
bootstrap();